export function findById(id){return TASKS.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return TASKS.slice();return TASKS.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export function enabledOnly(){return TASKS.filter(x=>x.enabled!==false)}
export const COUNT=TASKS.length;

